  // Independent emotional reading. A pada number is factual, not a prose gate.
  const richAriesMoon = lunarKnown && lunarIndex === 0 && lunarHouse === 8;
  const richMoonSun = richAriesMoon && sun.signIndex === 10 && sun.houseNumber === 6 && !sun.isBoundaryUncertain;
